from pydantic import BaseModel, Field

class Paper(BaseModel):
    """Represents one provided paper and its outgoing citation relationships."""
    title: str | None = Field(description="The title of this paper as it appears in the document")
    references_provided_papers: list[str] = Field(
        description="Titles of OTHER provided papers (from the known collection) that appear in this paper's reference list"
    )

class Parse(BaseModel):
    """Aggregates extraction results for a single document processed."""
    papers: list[Paper]
